        '  <button class="tab" onclick="switchTab(\'combobot\',this)">🎯 COMBO BOT</button>\n</div>\n\n<!-- ═══════════════════════════════\n',
        '  <button class="tab" onclick="switchTab(\'combobot\',this)">🎯 COMBO BOT</button>\n</div>\n\n<!-- ═══════════════════════════════\n     TAB 0: COMMAND CENTER (Decision-First Flow, default view)\n═══════════════════════════════ -->\n<div class="panel active" id="tab-command">\n\n  <!-- VERDICT BOX -->\n  <div id="cmd-verdict-box" style="border-radius:4px;padding:16px;text-align:center;margin-bottom:8px;background:#1a1a1a;border:2px solid #333">\n    <div id="cmd-coin-name" style="font-size:11px;color:var(--grey);letter-spacing:.5px;margin-bottom:4px">Scanning for best setup...</div>\n    <div id="cmd-verdict-label" style="font-size:32px;font-weight:bold;color:var(--grey);letter-spacing:1px">—</div>\n    <div id="cmd-verdict-sub" style="font-size:12px;color:var(--grey);margin-top:4px">Score — / 100 &nbsp;|&nbsp; Confidence —%</div>\n  </div>\n\n  <!-- QUICK PLAN -->\n  <div class="card">\n    <div class="ch" style="font-size:10px">📋 Quick Plan</div>\n    <div class="cb">\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px">\n        <div><span style="color:var(--grey);font-size:9px">ENTRY</span><br><b id="cmd-entry">—</b></div>\n        <div><span style="color:var(--grey);font-size:9px">STOP LOSS</span><br><b id="cmd-sl" style="color:var(--red)">—</b></div>\n        <div><span style="color:var(--grey);font-size:9px">TAKE PROFIT</span><br><b id="cmd-tp" style="color:var(--green)">—</b></div>\n        <div><span style="color:var(--grey);font-size:9px">SIZE</span><br><b id="cmd-size">—</b></div>\n      </div>\n      <button id="cmd-execute-btn" disabled class="exec-btn go pg exec-btn-primary" onclick="cmdExecuteTrade()" style="margin-top:12px;opacity:.4;cursor:not-allowed;background:#222;color:#666;border-color:#333">\n        EXECUTE TRADE NOW\n      </button>\n    </div>\n  </div>\n\n  <!-- WHY? -->\n  <div class="card">\n    <div class="ch" style="font-size:10px">🤔 Why?</div>\n    <div class="cb">\n      <ul id="cmd-why-list" style="margin:0;padding-left:18px;font-size:11px;line-height:1.9;color:var(--grey)">\n        <li>Waiting for scan data...</li>\n      </ul>\n    </div>\n  </div>\n\n  <!-- ACCORDIONS -->\n  <div class="card" style="margin-top:8px">\n    <div class="ch" style="font-size:10px;cursor:pointer" onclick="toggleAccordion(\'acc-chart\')">\n      <span>📈 Live Chart &amp; Indicators</span><span id="acc-chart-icon" style="color:var(--grey);font-size:9px">▸</span>\n    </div>\n    <div id="acc-chart" class="cb" style="display:none;font-size:10px"></div>\n  </div>\n  <div class="card" style="margin-top:8px">\n    <div class="ch" style="font-size:10px;cursor:pointer" onclick="toggleAccordion(\'acc-whale\')">\n      <span>🐋 Whale Copy Data</span><span id="acc-whale-icon" style="color:var(--grey);font-size:9px">▸</span>\n    </div>\n    <div id="acc-whale" class="cb" style="display:none;font-size:10px"></div>\n  </div>\n  <div class="card" style="margin-top:8px">\n    <div class="ch" style="font-size:10px;cursor:pointer" onclick="toggleAccordion(\'acc-history\')">\n      <span>📜 Trade History</span><span id="acc-history-icon" style="color:var(--grey);font-size:9px">▸</span>\n    </div>\n    <div id="acc-history" class="cb" style="display:none;font-size:10px"></div>\n  </div>\n  <div class="card" style="margin-top:8px">\n    <div class="ch" style="font-size:10px;cursor:pointer" onclick="toggleAccordion(\'acc-onchain\')">\n      <span>⛓ On-Chain Flow</span><span id="acc-onchain-icon" style="color:var(--grey);font-size:9px">▸</span>\n    </div>\n    <div id="acc-onchain" class="cb" style="display:none;font-size:10px"></div>\n  </div>\n</div>\n\n<!-- ═══════════════════════════════\n',
