        "  if(name==='sniper' && !chart) setTimeout(function(){initChart();fetchChart();},500);\n}\n\nfunction toggleMoreTabs(){\n  const strip=document.getElementById('more-tabs-row');\n  const btn=document.getElementById('more-tabs-btn');\n  if(!strip) return;\n  const show = strip.style.display==='none';\n  strip.style.display = show ? 'flex' : 'none';\n  if(btn) btn.textContent = show ? 'Less ▴' : 'More ▾';\n}\n\n",
